from __future__ import annotations

import json
from typing import Any, List, Tuple

from .errors import OntologyError

# token 种类
_TOK_LBRACE = "LBRACE"
_TOK_RBRACE = "RBRACE"
_TOK_DOT = "DOT"
_TOK_STAR = "STAR"
_TOK_VAR = "VAR"
_TOK_NAME = "NAME"
_TOK_STRING = "STRING"

_DELIMITERS = frozenset('{}."?*')

# 模式项：("?", 变量名) 或 ("=", 字面值)
_VAR = "?"
_LIT = "="


class QueryResult:
    """查询结果：投影变量元组 + 等宽不可变字符串行元组。

    rows 已按投影取值去重并按字典序排序；无匹配时为空元组。
